from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def replace_once(path: str, old: str, new: str) -> None:
    target = ROOT / path
    text = target.read_text(encoding="utf-8")
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{path}: expected exactly one anchor, found {count}")
    target.write_text(text.replace(old, new, 1), encoding="utf-8")


def replace_between(path: str, start: str, end: str, replacement: str) -> None:
    target = ROOT / path
    text = target.read_text(encoding="utf-8")
    start_index = text.find(start)
    if start_index < 0:
        raise RuntimeError(f"{path}: start anchor not found")
    end_index = text.find(end, start_index)
    if end_index < 0:
        raise RuntimeError(f"{path}: end anchor not found")
    updated = text[:start_index] + replacement + text[end_index:]
    target.write_text(updated, encoding="utf-8")


def patch_storage() -> None:
    replace_once(
        "core/storage_migration.py",
        "from datetime import datetime\n",
        "from dataclasses import dataclass\nfrom datetime import datetime\n",
    )
    replace_once(
        "core/storage_migration.py",
        "FileSnapshot = tuple[os.stat_result, str, int]\n",
        """FileSnapshot = tuple[os.stat_result, str, int]\n\n\n@dataclass(frozen=True)\nclass DirectorySnapshot:\n    \"\"\"Stable directory identity plus a deterministic child-entry inventory.\"\"\"\n\n    st_dev: int\n    st_ino: int\n    entries: tuple[tuple[str, int, int, int], ...]\n""",
    )
    old = '''def _directory_identity(path: Path, label: str) -> os.stat_result:\n    try:\n        value = path.lstat()\n    except OSError as exc:\n        raise StorageOperationError(f"cannot inspect {label}: {exc}") from exc\n    if not stat.S_ISDIR(value.st_mode):\n        raise StorageOperationError(f"{label} must be a directory: {path}")\n    return value\n\n\ndef _require_unchanged_directory(\n    path: Path, expected: os.stat_result, label: str\n) -> None:\n    current = _directory_identity(path, label)\n    identity = (\n        current.st_dev,\n        current.st_ino,\n        current.st_mtime_ns,\n        current.st_ctime_ns,\n    )\n    expected_identity = (\n        expected.st_dev,\n        expected.st_ino,\n        expected.st_mtime_ns,\n        expected.st_ctime_ns,\n    )\n    if identity != expected_identity:\n        raise StorageOperationError(f"{label} changed during verification")\n'''
    new = '''def _directory_entry_inventory(\n    path: Path, label: str\n) -> tuple[tuple[str, int, int, int], ...]:\n    \"\"\"Return a stable, no-follow inventory for immediate directory entries.\"\"\"\n\n    entries: list[tuple[str, int, int, int]] = []\n    try:\n        with os.scandir(path) as iterator:\n            for entry in iterator:\n                try:\n                    entry_stat = entry.stat(follow_symlinks=False)\n                except OSError as exc:\n                    raise StorageOperationError(\n                        f"cannot inspect {label} entry {entry.name!r}: {exc}"\n                    ) from exc\n                entries.append((\n                    entry.name,\n                    entry_stat.st_dev,\n                    entry_stat.st_ino,\n                    stat.S_IFMT(entry_stat.st_mode),\n                ))\n    except StorageOperationError:\n        raise\n    except OSError as exc:\n        raise StorageOperationError(f"cannot enumerate {label}: {exc}") from exc\n    entries.sort(key=lambda item: item[0])\n    return tuple(entries)\n\n\ndef _directory_identity(path: Path, label: str) -> DirectorySnapshot:\n    try:\n        value = path.lstat()\n    except OSError as exc:\n        raise StorageOperationError(f"cannot inspect {label}: {exc}") from exc\n    if not stat.S_ISDIR(value.st_mode):\n        raise StorageOperationError(f"{label} must be a directory: {path}")\n    return DirectorySnapshot(\n        st_dev=value.st_dev,\n        st_ino=value.st_ino,\n        entries=_directory_entry_inventory(path, label),\n    )\n\n\ndef _require_unchanged_directory(\n    path: Path, expected: DirectorySnapshot, label: str\n) -> None:\n    current = _directory_identity(path, label)\n    if current != expected:\n        raise StorageOperationError(f"{label} changed during verification")\n'''
    replace_once("core/storage_migration.py", old, new)


def patch_retrieval_config() -> None:
    old = '''# Closed ranges for every tunable knob: (min, max, type).\n# k is the only integer; everything else is a float weight/threshold.\n_BOUNDS: Dict[str, Any] = {\n    "k":                   (1,   50,  int),\n    "min_similarity":      (0.0, 1.0, float),\n    "graph_walk_hops":     (0,   5,   int),\n    "graph_walk_decay":    (0.0, 1.0, float),\n    "significance_weight": (0.0, 2.0, float),\n}\n'''
    new = '''# Closed ranges for every tunable knob: (min, max, type).\n# Graph work ceilings are integers; score/decay knobs are bounded floats.\n_BOUNDS: Dict[str, Any] = {\n    "k":                            (1,    50,   int),\n    "min_similarity":               (0.0,  1.0,  float),\n    "graph_walk_hops":              (0,    5,    int),\n    "graph_walk_decay":             (0.0,  1.0,  float),\n    "graph_walk_edges_per_node":    (1,    256,  int),\n    "graph_walk_frontier_limit":    (1,    2048, int),\n    "graph_walk_candidate_limit":   (1,    4096, int),\n    "significance_weight":          (0.0,  2.0,  float),\n}\n'''
    replace_once("core/retrieval_config.py", old, new)
    replace_once(
        "core/retrieval_config.py",
        '''    graph_walk_hops: int = 2            # spreading-activation depth\n    graph_walk_decay: float = 0.5       # activation damping per hop\n    significance_weight: float = 0.5    # salience contribution in vector_search\n''',
        '''    graph_walk_hops: int = 2            # spreading-activation depth\n    graph_walk_decay: float = 0.5       # activation damping per hop\n    graph_walk_edges_per_node: int = 32 # eligible outgoing edges inspected per node\n    graph_walk_frontier_limit: int = 128 # max nodes activated in any next-hop frontier\n    graph_walk_candidate_limit: int = 256 # max distinct graph-origin candidates per query\n    significance_weight: float = 0.5    # salience contribution in vector_search\n''',
    )


def patch_l3_graph() -> None:
    replace_once(
        "core/l3_graph.py",
        '''def _salience_score(similarity: float, significance: Any) -> float:\n    """Similarity boosted by the node's significance (default significance=0.5)."""\n    try:\n        sig = float(significance)\n    except (TypeError, ValueError):\n        sig = 0.5\n    return similarity * (1.0 + get_retrieval_config().significance_weight * sig)\n''',
        '''def _salience_score(similarity: float, significance: Any) -> float:\n    """Similarity boosted by the node's significance (default significance=0.5)."""\n    try:\n        sig = float(significance)\n    except (TypeError, ValueError):\n        sig = 0.5\n    return similarity * (1.0 + get_retrieval_config().significance_weight * sig)\n\n\ndef _normalize_edge_limit(limit: Optional[int]) -> Optional[int]:\n    """Validate an optional edge-read ceiling; bool is not an integer limit."""\n    if limit is None:\n        return None\n    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 0:\n        raise ValueError("edge limit must be a non-negative integer or None")\n    return limit\n''',
    )
    replace_once(
        "core/l3_graph.py",
        '''    def get_edges(\n        self, fact_id: str, rel_type: Optional[str] = None,\n    ) -> List[Dict[str, Any]]:\n        """\n        A fact's outgoing edges together with their props (unlike neighbors,\n        which returns only nodes). Element: {rel_type, target, props}.\n        Needed to read the episodic who/where/when context from edges.\n        """\n''',
        '''    def get_edges(\n        self, fact_id: str, rel_type: Optional[str] = None,\n        limit: Optional[int] = None,\n    ) -> List[Dict[str, Any]]:\n        """\n        A fact's outgoing edges together with their props (unlike neighbors,\n        which returns only nodes). Element: {rel_type, target, props}.\n        ``limit`` provides a deterministic query-local work ceiling.\n        """\n''',
    )
    replace_once(
        "core/l3_graph.py",
        '''    def get_edges(\n        self, fact_id: str, rel_type: Optional[str] = None,\n    ) -> List[Dict[str, Any]]:\n        out = []\n        for src, rel, dst, props in self._edges:\n            if src != fact_id:\n                continue\n            if rel_type is not None and rel != rel_type:\n                continue\n            out.append({"rel_type": rel, "target": dst, "props": dict(props)})\n        return out\n''',
        '''    def get_edges(\n        self, fact_id: str, rel_type: Optional[str] = None,\n        limit: Optional[int] = None,\n    ) -> List[Dict[str, Any]]:\n        limit = _normalize_edge_limit(limit)\n        out = []\n        for src, rel, dst, props in self._edges:\n            if src != fact_id:\n                continue\n            if rel_type is not None and rel != rel_type:\n                continue\n            out.append({"rel_type": rel, "target": dst, "props": dict(props)})\n        out.sort(key=lambda edge: (\n            str(edge["rel_type"]),\n            str(edge["target"]),\n            json.dumps(edge["props"], ensure_ascii=False, sort_keys=True, separators=(",", ":")),\n        ))\n        return out if limit is None else out[:limit]\n''',
    )
    replace_once(
        "core/l3_graph.py",
        '''    @_synchronized\n    def get_edges(\n        self, fact_id: str, rel_type: Optional[str] = None,\n    ) -> List[Dict[str, Any]]:\n        q = "SELECT rel_type, dst, props FROM edges WHERE src = ?"\n        params: List[Any] = [fact_id]\n        if rel_type is not None:\n            q += " AND rel_type = ?"\n            params.append(rel_type)\n        return [{"rel_type": r["rel_type"], "target": r["dst"],\n                 "props": json.loads(r["props"])}\n                for r in self._conn.execute(q, params)]\n''',
        '''    @_synchronized\n    def get_edges(\n        self, fact_id: str, rel_type: Optional[str] = None,\n        limit: Optional[int] = None,\n    ) -> List[Dict[str, Any]]:\n        limit = _normalize_edge_limit(limit)\n        q = "SELECT rel_type, dst, props FROM edges WHERE src = ?"\n        params: List[Any] = [fact_id]\n        if rel_type is not None:\n            q += " AND rel_type = ?"\n            params.append(rel_type)\n        q += " ORDER BY rel_type, dst, props"\n        if limit is not None:\n            q += " LIMIT ?"\n            params.append(limit)\n        return [{"rel_type": r["rel_type"], "target": r["dst"],\n                 "props": json.loads(r["props"])}\n                for r in self._conn.execute(q, params)]\n''',
    )
    replace_once(
        "core/l3_graph.py",
        '''    def get_edges(\n        self, fact_id: str, rel_type: Optional[str] = None,\n    ) -> List[Dict[str, Any]]:\n        import base64\n        import json\n        cypher = "MATCH (a:Fact {fact_id: $id})-[e:EDGE]->(b:Fact)"\n        params: Dict[str, Any] = {"id": fact_id}\n        if rel_type is not None:\n            cypher += " WHERE e.rel_type = $rt"\n            params["rt"] = rel_type\n        res = self._conn.execute(\n            f"{cypher} RETURN e.rel_type, b.fact_id, e.props", params)\n        out = []\n        while res.has_next():\n            rel, target, raw = res.get_next()\n            try:\n                props = json.loads(base64.b64decode(raw)) if raw else {}\n            except (ValueError, TypeError):\n                props = {}\n            out.append({"rel_type": rel, "target": target, "props": props})\n        return out\n''',
        '''    def get_edges(\n        self, fact_id: str, rel_type: Optional[str] = None,\n        limit: Optional[int] = None,\n    ) -> List[Dict[str, Any]]:\n        import base64\n        import json\n        limit = _normalize_edge_limit(limit)\n        cypher = "MATCH (a:Fact {fact_id: $id})-[e:EDGE]->(b:Fact)"\n        params: Dict[str, Any] = {"id": fact_id}\n        if rel_type is not None:\n            cypher += " WHERE e.rel_type = $rt"\n            params["rt"] = rel_type\n        query = f"{cypher} RETURN e.rel_type, b.fact_id, e.props ORDER BY e.rel_type, b.fact_id"\n        if limit is not None:\n            query += f" LIMIT {limit}"\n        res = self._conn.execute(query, params)\n        out = []\n        while res.has_next():\n            rel, target, raw = res.get_next()\n            try:\n                props = json.loads(base64.b64decode(raw)) if raw else {}\n            except (ValueError, TypeError):\n                props = {}\n            out.append({"rel_type": rel, "target": target, "props": props})\n        return out\n''',
    )
    replace_once(
        "core/l3_graph.py",
        '''    def get_edges(self, fact_id, rel_type=None) -> List[Dict[str, Any]]:\n        import json\n        cypher = "MATCH (a:Fact {fact_id: $id})-[e:EDGE]->(b:Fact)"\n        params = {"id": fact_id}\n        if rel_type is not None:\n            cypher += " WHERE e.rel_type = $rt"\n            params["rt"] = rel_type\n        rows = self._run(\n            cypher + " RETURN e.rel_type AS rt, b.fact_id AS t, e.props AS p", **params)\n        out = []\n        for r in rows:\n            try:\n                props = json.loads(r["p"]) if r["p"] else {}\n            except (ValueError, TypeError):\n                props = {}\n            out.append({"rel_type": r["rt"], "target": r["t"], "props": props})\n        return out\n''',
        '''    def get_edges(self, fact_id, rel_type=None, limit=None) -> List[Dict[str, Any]]:\n        import json\n        limit = _normalize_edge_limit(limit)\n        cypher = "MATCH (a:Fact {fact_id: $id})-[e:EDGE]->(b:Fact)"\n        params = {"id": fact_id}\n        if rel_type is not None:\n            cypher += " WHERE e.rel_type = $rt"\n            params["rt"] = rel_type\n        query = cypher + " RETURN e.rel_type AS rt, b.fact_id AS t, e.props AS p ORDER BY e.rel_type, b.fact_id"\n        if limit is not None:\n            query += f" LIMIT {limit}"\n        rows = self._run(query, **params)\n        out = []\n        for r in rows:\n            try:\n                props = json.loads(r["p"]) if r["p"] else {}\n            except (ValueError, TypeError):\n                props = {}\n            out.append({"rel_type": r["rt"], "target": r["t"], "props": props})\n        return out\n''',
    )


def patch_pipeline() -> None:
    old = '''# Activation propagation weights by edge type. Truth-maintenance edges do NOT\n# carry relevance: a fact is not "more relevant" because it is refuted\n# (CONTRADICTS) or because it is replaced (SUPERSEDED_BY) — otherwise graph-walk would lift\n# exactly the refuted/obsolete. Episodic association (CO_OCCURRED) and any\n# unknown types propagate normally (default weight 1.0).\n_WALK_EDGE_WEIGHTS = {\n    "CONTRADICTS": 0.0,\n    "SUPERSEDED_BY": 0.0,\n}\n_WALK_DEFAULT_EDGE_WEIGHT = 1.0\n'''
    new = '''# Activation propagation is default-deny. Graph edges are navigation signals,\n# not evidence or truth, and an edge writer must not gain ranking influence\n# merely by inventing a new relation type. Start conservatively with the one\n# explicitly associative relation already used by episodic recall.\n_WALK_EDGE_WEIGHTS = {\n    "CO_OCCURRED": 1.0,\n}\n_WALK_DEFAULT_EDGE_WEIGHT = 0.0\n'''
    replace_once("core/pipeline.py", old, new)

    start = '    for _hop in range(cfg.graph_walk_hops):\n'
    end = '    for nid, score in graph_score.items():\n'
    replacement = '''    # Bound even the initial vector-seed frontier. Stable score/fact-id order\n    # prevents backend insertion order from changing graph work.\n    current = dict(sorted(\n        current.items(), key=lambda item: (-item[1], item[0])\n    )[:cfg.graph_walk_frontier_limit])\n\n    for _hop in range(cfg.graph_walk_hops):\n        nxt: Dict[str, float] = {}\n        for fid, act in sorted(current.items(), key=lambda item: item[0]):\n            # Only explicitly approved relation types are requested from the\n            # backend. Each backend receives a hard LIMIT so a dense node cannot\n            # materialize an unbounded outgoing-edge set for this query.\n            targets = []\n            remaining_edges = cfg.graph_walk_edges_per_node\n            for rel_type, weight in sorted(_WALK_EDGE_WEIGHTS.items()):\n                if remaining_edges <= 0:\n                    break\n                edges = graph.get_edges(\n                    fid, rel_type=rel_type, limit=remaining_edges\n                )\n                for edge in edges:\n                    remaining_edges -= 1\n                    node = graph.get_fact(edge["target"])\n                    if node is None or not _may_propagate_activation(node):\n                        continue\n                    targets.append((node, weight))\n            total_weight = sum(weight for _, weight in targets)\n            if total_weight <= 0.0:\n                continue\n            for node, weight in targets:\n                nid = node["fact_id"]\n                if nid in seeds:\n                    continue\n                share = act * cfg.graph_walk_decay * (weight / total_weight)\n                nxt[nid] = nxt.get(nid, 0.0) + share\n                node_cache[nid] = node\n        if not nxt:\n            break\n\n        # Highest activation wins; fact_id is the deterministic tie-breaker.\n        # Candidate and frontier ceilings are independent: one limits distinct\n        # graph-origin results over the whole walk, the other limits work in\n        # the next hop. Existing candidates may still accumulate activation.\n        ranked_nxt = sorted(nxt.items(), key=lambda item: (-item[1], item[0]))\n        bounded_next: Dict[str, float] = {}\n        for nid, val in ranked_nxt:\n            is_new_candidate = nid not in graph_score\n            if (is_new_candidate\n                    and len(graph_score) >= cfg.graph_walk_candidate_limit):\n                continue\n            graph_score[nid] = graph_score.get(nid, 0.0) + val\n            bounded_next[nid] = val\n            if len(bounded_next) >= cfg.graph_walk_frontier_limit:\n                break\n        if not bounded_next:\n            break\n        current = bounded_next\n\n'''
    replace_between("core/pipeline.py", start, end, replacement)


def write_tests() -> None:
    test_path = ROOT / "tests/test_pre_freeze_wave1.py"
    test_path.write_text('''from __future__ import annotations\n\nimport pytest\n\nfrom core import embedding, pipeline\nfrom core.l3_graph import MockL3Graph, SqliteL3Graph\nfrom core.retrieval_config import RetrievalConfig\n\n\nclass _BoundedGraph:\n    def __init__(self, edges):\n        self._fp = None\n        self.edges = list(edges)\n        self.calls = []\n        self.nodes = {\n            "seed": {\n                "fact_id": "seed", "claim": "seed", "source": "src",\n                "confidence": 1.0, "epistemic_state": "Validated",\n                "truth_status": "VERIFIED", "source_status": "EXTERNAL",\n                "restricted": False,\n            },\n            "assoc-a": {\n                "fact_id": "assoc-a", "claim": "assoc a", "source": "src",\n                "confidence": 1.0, "epistemic_state": "Validated",\n                "truth_status": "VERIFIED", "source_status": "EXTERNAL",\n                "restricted": False,\n            },\n            "assoc-b": {\n                "fact_id": "assoc-b", "claim": "assoc b", "source": "src",\n                "confidence": 1.0, "epistemic_state": "Validated",\n                "truth_status": "VERIFIED", "source_status": "EXTERNAL",\n                "restricted": False,\n            },\n            "sep": {\n                "fact_id": "sep", "claim": "separated", "source": "src",\n                "confidence": 1.0, "epistemic_state": "Validated",\n                "truth_status": "VERIFIED", "source_status": "EXTERNAL",\n                "restricted": False,\n            },\n            "deep": {\n                "fact_id": "deep", "claim": "deep", "source": "src",\n                "confidence": 1.0, "epistemic_state": "Validated",\n                "truth_status": "VERIFIED", "source_status": "EXTERNAL",\n                "restricted": False,\n            },\n        }\n\n    def embedder_fingerprint(self):\n        return self._fp\n\n    def set_embedder_fingerprint(self, value):\n        self._fp = value\n\n    def vector_search(self, _query_vector, k=5):\n        node = dict(self.nodes["seed"])\n        node["_relevance"] = 1.0\n        return [node][:k]\n\n    def get_edges(self, fact_id, rel_type=None, limit=None):\n        self.calls.append((fact_id, rel_type, limit))\n        out = [\n            dict(edge) for edge in self.edges\n            if edge["source"] == fact_id\n            and (rel_type is None or edge["rel_type"] == rel_type)\n        ]\n        out.sort(key=lambda edge: (edge["rel_type"], edge["target"]))\n        if limit is not None:\n            out = out[:limit]\n        return [{\n            "rel_type": edge["rel_type"],\n            "target": edge["target"],\n            "props": {},\n        } for edge in out]\n\n    def get_fact(self, fact_id):\n        node = self.nodes.get(fact_id)\n        return dict(node) if node is not None else None\n\n\ndef _cfg(**overrides):\n    values = dict(\n        k=3, min_similarity=0.0, graph_walk_hops=2, graph_walk_decay=0.5,\n        graph_walk_edges_per_node=32, graph_walk_frontier_limit=128,\n        graph_walk_candidate_limit=256, significance_weight=0.5,\n    )\n    values.update(overrides)\n    return RetrievalConfig(**values)\n\n\ndef test_graph_walk_is_default_deny_and_passes_backend_limit(monkeypatch):\n    graph = _BoundedGraph([\n        {"source": "seed", "rel_type": "SEPARATED_FROM", "target": "sep"},\n        {"source": "seed", "rel_type": "CO_OCCURRED", "target": "assoc-b"},\n        {"source": "seed", "rel_type": "CO_OCCURRED", "target": "assoc-a"},\n    ])\n    monkeypatch.setenv("VELANTRIM_EMBEDDER", "hashing")\n    embedding.reset_embedder()\n    monkeypatch.setattr(pipeline, "get_l3_graph", lambda: graph)\n    monkeypatch.setattr(\n        pipeline, "get_retrieval_config",\n        lambda: _cfg(graph_walk_hops=1, graph_walk_edges_per_node=1),\n    )\n\n    result = pipeline.retrieve("seed", k=3)\n    ids = {item["id"] for item in result}\n\n    assert "seed" in ids\n    assert "assoc-a" in ids\n    assert "assoc-b" not in ids\n    assert "sep" not in ids\n    assert graph.calls == [("seed", "CO_OCCURRED", 1)]\n\n\ndef test_graph_walk_frontier_and_candidate_limits_are_independent(monkeypatch):\n    graph = _BoundedGraph([\n        {"source": "seed", "rel_type": "CO_OCCURRED", "target": "assoc-a"},\n        {"source": "seed", "rel_type": "CO_OCCURRED", "target": "assoc-b"},\n        {"source": "assoc-a", "rel_type": "CO_OCCURRED", "target": "deep"},\n    ])\n    monkeypatch.setenv("VELANTRIM_EMBEDDER", "hashing")\n    embedding.reset_embedder()\n    monkeypatch.setattr(pipeline, "get_l3_graph", lambda: graph)\n    monkeypatch.setattr(\n        pipeline, "get_retrieval_config",\n        lambda: _cfg(\n            graph_walk_hops=2, graph_walk_frontier_limit=1,\n            graph_walk_candidate_limit=1,\n        ),\n    )\n\n    result = pipeline.retrieve("seed", k=5)\n    graph_ids = [item["id"] for item in result if item["origin"] == "graph"]\n\n    assert graph_ids == ["assoc-a"]\n    assert "deep" not in graph_ids\n\n\ndef test_mock_get_edges_is_deterministic_and_bounded():\n    graph = MockL3Graph()\n    graph.add_edge("a", "CO_OCCURRED", "z")\n    graph.add_edge("a", "CO_OCCURRED", "b")\n    graph.add_edge("a", "CO_OCCURRED", "m")\n\n    assert [e["target"] for e in graph.get_edges("a", "CO_OCCURRED", limit=2)] == ["b", "m"]\n    with pytest.raises(ValueError):\n        graph.get_edges("a", limit=-1)\n\n\ndef test_sqlite_get_edges_applies_order_and_limit():\n    graph = SqliteL3Graph(":memory:")\n    try:\n        graph.add_edge("a", "CO_OCCURRED", "z")\n        graph.add_edge("a", "CO_OCCURRED", "b")\n        graph.add_edge("a", "CO_OCCURRED", "m")\n        assert [e["target"] for e in graph.get_edges("a", "CO_OCCURRED", limit=2)] == ["b", "m"]\n    finally:\n        graph.close()\n\n\ndef test_retrieval_config_rejects_unbounded_graph_limits():\n    with pytest.raises(ValueError):\n        _cfg(graph_walk_edges_per_node=257)\n    with pytest.raises(ValueError):\n        _cfg(graph_walk_frontier_limit=2049)\n    with pytest.raises(ValueError):\n        _cfg(graph_walk_candidate_limit=4097)\n''', encoding="utf-8")


def main() -> None:
    patch_storage()
    patch_retrieval_config()
    patch_l3_graph()
    patch_pipeline()
    write_tests()


if __name__ == "__main__":
    main()
